  (10001,'spring',0,0,'봄의 첫 산책을 약속한다면 두 사람이 함께 찾고 싶은 봄 신호는요?',array['가지 끝에 맺힌 연둣빛 눈이요.', '바람에 흔들리는 새순을 보고 싶어요.', '두꺼운 외투를 벗어 든 사람이요.']),
  (10002,'spring',0,1,'아직 쌀쌀한 봄 저녁, 처음 만난 사람에게 어떤 제안을 해 주고 싶나요?',array['따뜻한 차가 있는 곳으로 가자고 해요.', '걷고 싶은지 먼저 물어볼래요.', '바람을 피할 수 있는 자리를 찾아봐요.']),
