  (10852,'foundation',0,1,'개천절에 본 문화유산 한 점을 다시 본다면, 어떤 점을 더 알고 싶나요?',array['누가 어떤 손길로 만들었는지요.', '그때는 매일 어떻게 썼는지요.', '오랜 세월 동안 어떻게 지켜 왔는지요.']),
  (10901,'memorial',0,0,'현충일에는 각자 어떤 방식으로 조용히 추모의 마음을 전하고 싶나요?',array['잠깐 하던 일을 멈추고 묵념할래요.', '이름 하나를 마음에 담아 둘래요.', '추모 글을 차분히 읽고 싶어요.']),
  (10902,'memorial',0,1,'현충일에 함께 읽을 기록을 고른다면 어떤 목소리에 귀 기울이고 싶나요?',array['가족이 간직해 온 편지 한 통이요.', '하루를 담은 평범한 사람의 일기요.', '오랜 시간이 지나 전한 증언이요.']);
